type Time = { instant: number; local: string };
const zone = new Intl.DateTimeFormat(\"en-US\", {
  timeZone: \"America/Chicago\", year: \"numeric\", month: \"2-digit\", day: \"2-digit\",
  hour: \"2-digit\", minute: \"2-digit\", second: \"2-digit\", hourCycle: \"h23\",
