    if (hr) { row.pulse_bpm = hr.data.VALUE_NUM as number; selected.push(hr); }
    if (wt) { row.weight_kg = Math.round((wt.data.VALUE_NUM as number) * 10) / 10; selected.push(wt); }
    row.evidence = evidence(...selected);
